// ============================================================================
// DMA_apb: APB4 register wrapper around DMA_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/DMA.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DMA.md
// ============================================================================
module DMA_apb #(
  parameter logic [3:0] AXI_ID = 4'd7
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C090100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [25:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd26) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [31:0]   c_src0;
  logic [31:0]   c_src1;
  logic [31:0]   c_src2;
  logic [31:0]   c_src3;
  logic [31:0]   c_dst0;
  logic [31:0]   c_dst1;
  logic [31:0]   c_dst2;
  logic [31:0]   c_dst3;
  logic [15:0]   c_len0;
  logic [15:0]   c_len1;
  logic [15:0]   c_len2;
  logic [15:0]   c_len3;
  logic          c_mode0;
  logic          c_mode1;
  logic          c_mode2;
  logic          c_mode3;
  logic [31:0]   c_fill0;
  logic [31:0]   c_fill1;
  logic [31:0]   c_fill2;
  logic [31:0]   c_fill3;
  logic          c_start0;
  logic          c_start1;
  logic          c_start2;
  logic          c_start3;
  logic [3:0]    c_pending;
  logic          c_busy;
  logic [1:0]    c_active_ch;
  logic          c_err;
  logic [31:0]   c_checksum;
  logic [31:0]   c_cycles;
  logic          c_done0;
  logic          c_done1;
  logic          c_done2;
  logic          c_done3;
  logic          c_err_irq;
  DMA_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .src0(c_src0),
    .src1(c_src1),
    .src2(c_src2),
    .src3(c_src3),
    .dst0(c_dst0),
    .dst1(c_dst1),
    .dst2(c_dst2),
    .dst3(c_dst3),
    .len0(c_len0),
    .len1(c_len1),
    .len2(c_len2),
    .len3(c_len3),
    .mode0(c_mode0),
    .mode1(c_mode1),
    .mode2(c_mode2),
    .mode3(c_mode3),
    .fill0(c_fill0),
    .fill1(c_fill1),
    .fill2(c_fill2),
    .fill3(c_fill3),
    .start0(c_start0),
    .start1(c_start1),
    .start2(c_start2),
    .start3(c_start3),
    .pending(c_pending),
    .busy(c_busy),
    .active_ch(c_active_ch),
    .err(c_err),
    .checksum(c_checksum),
    .cycles(c_cycles),
    .done0(c_done0),
    .done1(c_done1),
    .done2(c_done2),
    .done3(c_done3),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [4:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_SRC0;   // 12'h014 SRC0
  logic [31:0] r_DST0;   // 12'h018 DST0
  logic [15:0] r_LEN0;   // 12'h01C LEN0
  logic [31:0] r_FILL0;   // 12'h020 FILL0
  logic [31:0] r_SRC1;   // 12'h024 SRC1
  logic [31:0] r_DST1;   // 12'h028 DST1
  logic [15:0] r_LEN1;   // 12'h02C LEN1
  logic [31:0] r_FILL1;   // 12'h030 FILL1
  logic [31:0] r_SRC2;   // 12'h034 SRC2
  logic [31:0] r_DST2;   // 12'h038 DST2
  logic [15:0] r_LEN2;   // 12'h03C LEN2
  logic [31:0] r_FILL2;   // 12'h040 FILL2
  logic [31:0] r_SRC3;   // 12'h044 SRC3
  logic [31:0] r_DST3;   // 12'h048 DST3
  logic [15:0] r_LEN3;   // 12'h04C LEN3
  logic [31:0] r_FILL3;   // 12'h050 FILL3
  logic [3:0] r_MODE;   // 12'h054 MODE
  logic [3:0] p_CMD;   // 12'h058 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_SRC0 <= 32'h0;
      r_DST0 <= 32'h0;
      r_LEN0 <= 16'h0;
      r_FILL0 <= 32'h0;
      r_SRC1 <= 32'h0;
      r_DST1 <= 32'h0;
      r_LEN1 <= 16'h0;
      r_FILL1 <= 32'h0;
      r_SRC2 <= 32'h0;
      r_DST2 <= 32'h0;
      r_LEN2 <= 16'h0;
      r_FILL2 <= 32'h0;
      r_SRC3 <= 32'h0;
      r_DST3 <= 32'h0;
      r_LEN3 <= 16'h0;
      r_FILL3 <= 32'h0;
      r_MODE <= 4'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[4:0] & wmask[4:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[4:0]) | (PWDATA[4:0] & wmask[4:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_SRC0 <= (r_SRC0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[6]) r_DST0 <= (r_DST0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_LEN0 <= (r_LEN0 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[8]) r_FILL0 <= (r_FILL0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_SRC1 <= (r_SRC1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_DST1 <= (r_DST1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_LEN1 <= (r_LEN1 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[12]) r_FILL1 <= (r_FILL1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_SRC2 <= (r_SRC2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_DST2 <= (r_DST2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_LEN2 <= (r_LEN2 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[16]) r_FILL2 <= (r_FILL2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_SRC3 <= (r_SRC3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[18]) r_DST3 <= (r_DST3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[19]) r_LEN3 <= (r_LEN3 & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[20]) r_FILL3 <= (r_FILL3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[21]) r_MODE <= (r_MODE & ~wmask[3:0]) | (PWDATA[3:0] & wmask[3:0]);
      p_CMD <= (wr && hit[22]) ? PWDATA[3:0] & wmask[3:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_src0 = r_SRC0[31:0];
  assign c_dst0 = r_DST0[31:0];
  assign c_len0 = r_LEN0[15:0];
  assign c_fill0 = r_FILL0[31:0];
  assign c_src1 = r_SRC1[31:0];
  assign c_dst1 = r_DST1[31:0];
  assign c_len1 = r_LEN1[15:0];
  assign c_fill1 = r_FILL1[31:0];
  assign c_src2 = r_SRC2[31:0];
  assign c_dst2 = r_DST2[31:0];
  assign c_len2 = r_LEN2[15:0];
  assign c_fill2 = r_FILL2[31:0];
  assign c_src3 = r_SRC3[31:0];
  assign c_dst3 = r_DST3[31:0];
  assign c_len3 = r_LEN3[15:0];
  assign c_fill3 = r_FILL3[31:0];
  assign c_mode0 = r_MODE[0:0];
  assign c_mode1 = r_MODE[1:1];
  assign c_mode2 = r_MODE[2:2];
  assign c_mode3 = r_MODE[3:3];
  assign c_start0 = p_CMD[0:0];
  assign c_start1 = p_CMD[1:1];
  assign c_start2 = p_CMD[2:2];
  assign c_start3 = p_CMD[3:3];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done0;
    irq_set[1] = c_done1;
    irq_set[2] = c_done2;
    irq_set[3] = c_done3;
    irq_set[4] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_SRC0);
      10'd6: apb_rdata = 32'(r_DST0);
      10'd7: apb_rdata = 32'(r_LEN0);
      10'd8: apb_rdata = 32'(r_FILL0);
      10'd9: apb_rdata = 32'(r_SRC1);
      10'd10: apb_rdata = 32'(r_DST1);
      10'd11: apb_rdata = 32'(r_LEN1);
      10'd12: apb_rdata = 32'(r_FILL1);
      10'd13: apb_rdata = 32'(r_SRC2);
      10'd14: apb_rdata = 32'(r_DST2);
      10'd15: apb_rdata = 32'(r_LEN2);
      10'd16: apb_rdata = 32'(r_FILL2);
      10'd17: apb_rdata = 32'(r_SRC3);
      10'd18: apb_rdata = 32'(r_DST3);
      10'd19: apb_rdata = 32'(r_LEN3);
      10'd20: apb_rdata = 32'(r_FILL3);
      10'd21: apb_rdata = 32'(r_MODE);
      10'd23: apb_rdata = 32'({c_err, c_active_ch, c_busy, c_pending});
      10'd24: apb_rdata = 32'({c_checksum});
      10'd25: apb_rdata = 32'({c_cycles});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
